using System;
using System.Globalization;

public struct Vec
{
    public double R, G, B;
    public Vec(double r, double g, double b) { R = r; G = g; B = b; }
}

public static class VecParser
{
    public static Vec ParseRgb(string raw)
    {
        if (raw == null) throw new FormatException();
        var parts = raw.Split(',');
        if (parts.Length != 3) throw new FormatException();
        double[] v = new double[3];
        for (int i = 0; i < 3; i++)
        {
            string s = parts[i].Trim();
            if (!double.TryParse(s, NumberStyles.Float, CultureInfo.InvariantCulture, out double d))
                throw new FormatException();
            if (double.IsNaN(d) || double.IsInfinity(d)) throw new FormatException();
            if (d < 0.0 || d > 1.0) throw new FormatException();
            v[i] = d;
        }
        return new Vec(v[0], v[1], v[2]);
    }
}
